import { Pool } from "pg";

export interface StoredResponse {
  status: number;
  body: unknown;
}

export class IdempotencyStore {
  constructor(private readonly db: Pool) {}

  async find(tenantId: string, key: string): Promise<{ fingerprint: string; response: StoredResponse } | null> {
    const { rows } = await this.db.query(
      `SELECT fingerprint, response_status, response_body
         FROM idempotency_keys
        WHERE tenant_id = $1 AND key = $2 AND created_at > now() - interval '24 hours'`,
      [tenantId, key]
    );
    if (rows.length === 0) return null;
    return {
      fingerprint: rows[0].fingerprint,
      response: { status: rows[0].response_status, body: rows[0].response_body },
    };
  }

  async save(tenantId: string, key: string, fingerprint: string, response: StoredResponse): Promise<void> {
    await this.db.query(
      `INSERT INTO idempotency_keys (tenant_id, key, fingerprint, response_status, response_body, created_at)
       VALUES ($1, $2, $3, $4, $5, now())
       ON CONFLICT (tenant_id, key) DO UPDATE
         SET fingerprint = EXCLUDED.fingerprint,
             response_status = EXCLUDED.response_status,
             response_body = EXCLUDED.response_body,
             created_at = now()`,
      [tenantId, key, fingerprint, response.status, JSON.stringify(response.body)]
    );
  }
}

import { createHash } from "crypto";
import { Router, Request, Response, NextFunction } from "express";
import { IdempotencyStore } from "./idempotencyStore";
import { TicketService } from "./ticketService";

interface TenantRequest extends Request {
  tenantId: string;
}

function fingerprintOf(body: unknown): string {
  return createHash("sha256").update(JSON.stringify(body)).digest("hex");
}

export function ticketRoutes(tickets: TicketService, idem: IdempotencyStore): Router {
  const router = Router();

  router.post("/tickets", async (req: Request, res: Response, next: NextFunction) => {
    const { tenantId } = req as TenantRequest;
    const key = req.header("Idempotency-Key");
    if (!key || key.length > 128) {
      res.status(400).json({ error: "idempotency_key_required" });
      return;
    }
    const { subject, description, requesterEmail, priority } = req.body ?? {};
    if (typeof subject !== "string" || subject.trim() === "" || typeof requesterEmail !== "string") {
      res.status(422).json({ error: "invalid_ticket" });
      return;
    }

    const fingerprint = fingerprintOf({ subject, description, requesterEmail, priority });
    try {
      const existing = await idem.find(tenantId, key);
      if (existing) {
        if (existing.fingerprint !== fingerprint) {
          res.status(422).json({ error: "idempotency_key_reused" });
          return;
        }
        res.status(existing.response.status).json(existing.response.body);
        return;
      }

      const ticket = await tickets.create(tenantId, {
        subject: subject.trim(),
        description: description ?? "",
        requesterEmail,
        priority: priority ?? "normal",
      });
      const body = { id: ticket.id, number: ticket.number, status: ticket.status };
      await idem.save(tenantId, key, fingerprint, { status: 201, body });
      res.status(201).json(body);
    } catch (err) {
      next(err);
    }
  });

  return router;
}

import { Pool } from "pg";

export interface NewTicket {
  subject: string;
  description: string;
  requesterEmail: string;
  priority: "low" | "normal" | "high" | "urgent";
}

export interface Ticket {
  id: string;
  number: number;
  status: "open";
}

export class TicketService {
  constructor(private readonly db: Pool, private readonly notify: (t: Ticket, email: string) => Promise<void>) {}

  async create(tenantId: string, input: NewTicket): Promise<Ticket> {
    const { rows } = await this.db.query(
      `INSERT INTO tickets (tenant_id, number, subject, description, requester_email, priority, status)
       VALUES ($1, (SELECT coalesce(max(number), 0) + 1 FROM tickets WHERE tenant_id = $1), $2, $3, $4, $5, 'open')
       RETURNING id, number, status`,
      [tenantId, input.subject, input.description, input.requesterEmail, input.priority]
    );
    const ticket: Ticket = rows[0];
    await this.notify(ticket, input.requesterEmail);
    return ticket;
  }
}
